import { json, ActionFunctionArgs } from '@remix-run/node';
import knex from '~/knex.server';
import { requireMarketerSession } from '~/auth.server';

export async function action({ request, params }: ActionFunctionArgs) {
  const marketer = await requireMarketerSession(request);
  const formData = await request.formData();
  const dailyBudget = parseFloat(formData.get('dailyBudget') as string);

  // Updates marketing campaign budget limit
  await knex('ad_campaigns')
    .where({ id: params.campaignId })
    .update({ daily_budget: dailyBudget, updated_at: new Date() });

  return json({ success: true, campaignId: params.campaignId, newBudget: dailyBudget });
}

corrected_code:
import { json, ActionFunctionArgs } from '@remix-run/node';
import knex from '~/knex.server';
import { requireMarketerSession } from '~/auth.server';

export async function action({ request, params }: ActionFunctionArgs) {
  const marketer = await requireMarketerSession(request);
  const formData = await request.formData();
  const dailyBudget = parseFloat(formData.get('dailyBudget') as string);

  const campaign = await knex('ad_campaigns')
    .where({ id: params.campaignId, agency_id: marketer.agencyId })
    .first();
  if (!campaign) {
    return json({ error: 'Forbidden: campaign does not belong to your agency' }, { status: 403 });
  }

  await knex('ad_campaigns')
    .where({ id: params.campaignId, agency_id: marketer.agencyId })
    .update({ daily_budget: dailyBudget, updated_at: new Date() });

  return json({ success: true, campaignId: params.campaignId, newBudget: dailyBudget });
}
